SELECT NVL(MAX(TR_SEQ_NO), 0)
  FROM SST0WC
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD = #{trYmd}
   AND TR_CD = #{trCd}
   AND CURRENCY = 'KRW'

SELECT COUNT(*)
  FROM SST0WC
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD = #{trYmd}
   AND TR_CD = #{trCd}
   AND FUND_CD = #{fundCd}
   AND TR_SEQ_NO = #{trSeqNo}
   AND CURRENCY = 'KRW'

mapper.update:
UPDATE SST0WC
   SET TR_AEK = NVL(#{trAek, jdbcType=NUMERIC}, 0)
     , FCUR_TR_AEK = NVL(#{fcurTrAek, jdbcType=NUMERIC}, 0)
     , TR_CO_CD = #{trCoCd, jdbcType=VARCHAR}
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD = #{trYmd}
   AND TR_CD = #{trCd}
   AND FUND_CD = #{fundCd}
   AND TR_SEQ_NO = #{trSeqNo}
   AND CURRENCY = 'KRW'

